// trackDefaultRangeChunks / trackDefaultUpdateInterval are the EntityType.Builder ctor defaults
// (clientTrackingRange = 5, updateInterval = 3) -- the fallback for a type absent from the table
// (never in practice; the table is complete for 26.2).
//
//	[VERIFIED javap EntityType$Builder.<init>: iconst_5 putfield clientTrackingRange; iconst_3
//	 putfield updateInterval.]
const (
	trackDefaultRangeChunks      = 5
	trackDefaultUpdateInterval   = 3
	maxClientTrackingRangeChunks = 32 // the largest table value (player/mannequin) -- the broad-phase window
)

// trackParamsFor returns the (clientTrackingRange, updateInterval) for an entity type, falling back
// to the Builder defaults for an unknown type. Cite EntityType.clientTrackingRange/updateInterval.
func trackParamsFor(typ entity.ID) trackParams {
	if tp, ok := trackParamsByType[typ]; ok {
		return tp
	}
	return trackParams{rangeChunks: trackDefaultRangeChunks, updateInterval: trackDefaultUpdateInterval}
}

// entityTrackRangeChunks is the entity's clientTrackingRange in CHUNKS. Cite EntityType.clientTrackingRange.
func entityTrackRangeChunks(typ entity.ID) int { return trackParamsFor(typ).rangeChunks }

// entityUpdateInterval is the entity's updateInterval in TICKS -- the ServerEntity.sendChanges
// tickCount % updateInterval gate. Cite EntityType.updateInterval.
func entityUpdateInterval(typ entity.ID) int { return trackParamsFor(typ).updateInterval }

// entityInTrackRange is the ChunkMap.TrackedEntity.updatePlayer distance gate: an entity is visible
// to a player at (px,pz) with view distance viewDistChunks when the horizontal Euclidean distance in
// BLOCKS satisfies dx*dx + dz*dz <= d*d, where d = min(clientTrackingRange*16, viewDistance*16). A
// type with clientTrackingRange 0 (marker) is never tracked (ChunkMap.addEntity returns early when
// range == 0), so this returns false for it.
//
//	[VERIFIED javap ChunkMap$TrackedEntity.updatePlayer: subtract player-entity pos; d = min(
//	 getEffectiveRange(), getPlayerViewDistance*16); dx*dx + dz*dz (X and Z only) <= d*d. ChunkMap
//	 .addEntity: range = clientTrackingRange()*16; if range == 0 return (untracked).]
func entityInTrackRange(ex, ez, px, pz float64, typ entity.ID, viewDistChunks int) bool {
	rangeChunks := entityTrackRangeChunks(typ)
	if rangeChunks <= 0 {
		return false // clientTrackingRange 0 (marker): never tracked
	}
	rangeBlocks := float64(rangeChunks * 16)
	viewBlocks := float64(viewDistChunks * 16)
	d := rangeBlocks
	if viewBlocks < d {
		d = viewBlocks
	}
	dx := ex - px
	dz := ez - pz
	return dx*dx+dz*dz <= d*d
}
